import{_ as t,o,c as r,a2 as d}from"./chunks/framework.C8nVztS1.js";const u=JSON.parse('{"title":"Troubleshooting","description":"Common errors, env flags, and untestutils doctor.","frontmatter":{"title":"Troubleshooting","description":"Common errors, env flags, and untestutils doctor.","outline":"deep"},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":1790411047000}'),s={name:"guide/troubleshooting.md"};function a(i,e,c,n,l,h){return o(),r("div",null,[...e[0]||(e[0]=[d(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> untestutils</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> untestutils</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --recipes</span></span></code></pre></div><p>Checks Node, peers (Vitest major 4|5), configs, and <code>recipes.ts</code>. <code>doctor --recipes</code> lists registered ids.</p><h2 id="common-errors" tabindex="-1">Common errors <a class="header-anchor" href="#common-errors" aria-label="Permalink to &quot;Common errors&quot;">​</a></h2><p><strong>unknown recipe id</strong> — <code>defineRecipes({ … }, import.meta.url)</code> and pass <code>recipes</code> into the plugin so workers re-import the module. Error messages list <strong>known ids</strong> when the registry is loaded.</p><p><strong>prewarm id not found</strong> — same: id must exist in the recipes module; message lists known ids.</p><p><strong>no harness url</strong> — call <code>useHarness</code> or list the id in <code>prewarm</code> before using <code>page</code> / <code>baseURL</code>.</p><p><strong>Playwright picked up <code>*.test.ts</code></strong> — <code>createPlaywrightConfig</code> defaults to <code>testMatch: &#39;**/*.spec.ts&#39;</code>. Override via <code>testMatch</code> if needed.</p><p><strong>Config pulled in fixtures</strong> — use <code>untestutils/vitest/plugin</code> in config, not <code>untestutils/vitest</code>.</p><p><strong>Ready hang / readiness failed</strong> — local servers bind <code>ctx.host</code> (default <code>127.0.0.1</code>, override with <code>UNTESTUTILS_BIND_HOST</code>). Ready probes TCP then HTTP; wildcard binds like <code>0.0.0.0</code> still probe <code>127.0.0.1</code>. For <code>host()</code>, set <code>readyTimeoutMs</code> / <code>readyPath</code>, or <code>skipReady: true</code> if the URL is already up. Drivers that wait inside <code>start</code> use a noop <code>ready</code> so the orchestrator does not probe twice.</p><p><strong>Tempted to use <code>run: &#39;dev&#39;</code> to skip builds?</strong> Don’t — that mode is for HMR / file-watcher specs only (<code>share: &#39;never&#39;</code>). Normal e2e should use <code>server</code> / <code>preview</code> / <code>static</code> so shared prepare stays warm. See <a href="/untestutils/guide/drivers#run-modes-nuxt">Drivers</a>.</p><p><strong>Orphan processes / leftover servers</strong> — hard-killed runs can leave registry entries and ports. Clear <code>.untestutils</code> and retry. Global setup calls <code>stopAllTargets</code>, which stops registry orphans internally. For ad-hoc servers use handles from <code>@untestutils/core</code>:</p><table tabindex="0"><thead><tr><th>API</th><th>Use</th></tr></thead><tbody><tr><td><code>spawnManaged(cmd, args)</code></td><td>Start → <code>stop()</code> / <code>alive()</code> / <code>logs()</code></td></tr><tr><td><code>stopAllTargets()</code></td><td>Drain live handles + registry</td></tr></tbody></table><p>Do not dig for PIDs or process groups — tear down via the handle.</p><h2 id="warm-cache-stale-artifacts" tabindex="-1">Warm cache / stale artifacts <a class="header-anchor" href="#warm-cache-stale-artifacts" aria-label="Permalink to &quot;Warm cache / stale artifacts&quot;">​</a></h2><p>Prepare reuse (<code>.ready</code> + content hash) does <strong>not</strong> hash build outputs like <code>.next/</code>, <code>dist/</code>, or <code>.output/</code>. Warm and registry-reuse paths call <code>recipe.verifyArtifact</code> when present — if the check throws, cache is invalidated and prepare runs again.</p><table tabindex="0"><thead><tr><th>Hook</th><th>When</th></tr></thead><tbody><tr><td><code>verifyAfterPrepare</code></td><td>Cold prepare only (also promoted to <code>verifyArtifact</code> when the latter is unset)</td></tr><tr><td><code>verifyArtifact(outDir)</code></td><td>After prepare <strong>and</strong> on warm / live / registry reuse</td></tr></tbody></table><p><strong>Shared fixture roots:</strong> do not run <code>dev</code> and a built mode (<code>server</code> / <code>preview</code> / <code>static</code>) against the same app directory if both write the same output (e.g. Next <code>.next</code> / <code>out</code>). Split fixtures (<code>next-dev</code> / <code>next-server</code> / <code>next-app-override</code>) or set distinct <code>distDir</code> / <code>outDir</code>. Playground <code>nextStaticOverride</code> uses its own fixture root.</p><p><strong>Next <code>distDir</code>:</strong> <code>verifyArtifact</code> / <code>BUILD_ID</code> checks respect <code>nextConfig.distDir</code>.</p><h2 id="reset-failure-unit-worker" tabindex="-1">Reset failure (unit worker) <a class="header-anchor" href="#reset-failure-unit-worker" aria-label="Permalink to &quot;Reset failure (unit worker)&quot;">​</a></h2><p>If <code>resetSharedApp</code> throws under <code>appIsolation: &#39;worker&#39;</code>, the shared app is disposed and the next test fails with <strong>call <code>restartSharedApp()</code></strong> until you restart.</p><p><strong>Empty setup / recipes never load</strong> — published facade must keep <code>vitest/setup-file</code> side effects (re-export, not a dead <code>await import</code>). Upgrade to a release that includes that fix.</p><h2 id="env" tabindex="-1">Env <a class="header-anchor" href="#env" aria-label="Permalink to &quot;Env&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th></tr></thead><tbody><tr><td><code>UNTESTUTILS_DEBUG=1</code></td><td>Verbose logs</td></tr><tr><td><code>UNTESTUTILS_QUIET=1</code> / <code>PROGRESS=0</code></td><td>Silence progress</td></tr><tr><td><code>UNTESTUTILS_SHARE=0</code></td><td>Disable share</td></tr><tr><td><code>UNTESTUTILS_ARTIFACTS_DIR</code></td><td>Custom artifacts root</td></tr><tr><td><code>UNTESTUTILS_BIND_HOST</code></td><td>Bind/probe host for local servers (default <code>127.0.0.1</code>; <code>localhost</code>/<code>::1</code> coerced to IPv4)</td></tr><tr><td><code>UNTESTUTILS_REMOTE_URL</code></td><td>Remote <code>host()</code> URL</td></tr><tr><td><code>UNTESTUTILS_BROWSER</code></td><td>Playwright engine for Vitest fixtures</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/untestutils/guide/getting-started">Getting started</a></li><li><a href="/untestutils/guide/how-it-works">How it works</a></li><li><a href="/untestutils/cli/">CLI</a></li></ul>`,26)])])}const g=t(s,[["render",a]]);export{u as __pageData,g as default};
